import Database from 'better-sqlite3';
import { randomInt, createHash } from 'crypto';

const dbPath = '/home/user/qwik-app/db.sqlite';

const db = new Database(dbPath);

// Enable WAL mode and set busy timeout to handle concurrency safely
db.pragma('journal_mode = WAL');
db.pragma('busy_timeout = 5000');

// Create table if it doesn't exist
db.exec(`
  CREATE TABLE IF NOT EXISTS api_keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    key_prefix TEXT NOT NULL,
    hashed_key TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
  )
`);

export interface ApiKeyRecord {
  id: number;
  name: string;
  key_prefix: string;
  hashed_key: string;
  status: 'active' | 'revoked';
  created_at: string;
}

export function generateApiKey(): { fullKey: string; prefix: string; hashedKey: string } {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let randomPart = '';
  for (let i = 0; i < 32; i++) {
    randomPart += chars[randomInt(0, chars.length)];
  }
  const fullKey = 'qk_' + randomPart;
  const prefix = fullKey.substring(0, 7);
  const hashedKey = createHash('sha256').update(fullKey).digest('hex');
  return { fullKey, prefix, hashedKey };
}

export function hashKey(key: string): string {
  return createHash('sha256').update(key).digest('hex');
}

export default db;

import type { RequestHandler } from "@builder.io/qwik-city";
import db, { generateApiKey } from "~/lib/db";

export const onPost: RequestHandler = async (requestEvent) => {
  try {
    const body = (await requestEvent.parseBody()) as any;
    const name = body?.name;

    if (!name || typeof name !== "string") {
      requestEvent.status(400);
      return requestEvent.json(400, { error: "Name is required and must be a string" });
    }

    const { fullKey, prefix, hashedKey } = generateApiKey();
    const createdAt = new Date().toISOString();
    const status = "active";

    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);
    const info = stmt.run(name, prefix, hashedKey, status, createdAt);
    const insertId = info.lastInsertRowid;

    requestEvent.status(201);
    return requestEvent.json(201, {
      id: Number(insertId),
      name,
      prefix,
      key: fullKey,
      status,
      created_at: createdAt,
    });
  } catch (err: any) {
    requestEvent.status(500);
    return requestEvent.json(500, { error: err.message || "Internal Server Error" });
  }
};

export const onGet: RequestHandler = async (requestEvent) => {
  try {
    const stmt = db.prepare(`
      SELECT id, name, key_prefix as prefix, status, created_at
      FROM api_keys
      ORDER BY id DESC
    `);
    const rows = stmt.all() as any[];

    const result = rows.map((row) => ({
      id: Number(row.id),
      name: row.name,
      prefix: row.prefix,
      status: row.status,
      created_at: row.created_at,
    }));

    return requestEvent.json(200, result);
  } catch (err: any) {
    requestEvent.status(500);
    return requestEvent.json(500, { error: err.message || "Internal Server Error" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import db from "~/lib/db";

export const onPost: RequestHandler = async (requestEvent) => {
  try {
    const id = requestEvent.params.id;

    // Check if the key exists
    const checkStmt = db.prepare("SELECT id FROM api_keys WHERE id = ?");
    const keyExists = checkStmt.get(id);

    if (!keyExists) {
      requestEvent.status(404);
      return requestEvent.json(404, { error: "Key not found" });
    }

    // Update status to 'revoked'
    const updateStmt = db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?");
    updateStmt.run(id);

    return requestEvent.json(200, {
      success: true,
      message: "API key has been successfully revoked",
    });
  } catch (err: any) {
    requestEvent.status(500);
    return requestEvent.json(500, { error: err.message || "Internal Server Error" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import db, { hashKey } from "~/lib/db";

export const onGet: RequestHandler = async (requestEvent) => {
  try {
    const apiKey = requestEvent.request.headers.get("X-API-Key");

    if (!apiKey) {
      requestEvent.status(401);
      return requestEvent.json(401, { error: "Unauthorized" });
    }

    const hashed = hashKey(apiKey);

    const stmt = db.prepare("SELECT status FROM api_keys WHERE hashed_key = ?");
    const record = stmt.get(hashed) as { status: string } | undefined;

    if (!record || record.status !== "active") {
      requestEvent.status(401);
      return requestEvent.json(401, { error: "Unauthorized" });
    }

    return requestEvent.json(200, {
      message: "Hello, authenticated developer!",
    });
  } catch (err: any) {
    requestEvent.status(500);
    return requestEvent.json(500, { error: err.message || "Internal Server Error" });
  }
};

import { component$, useSignal, $ } from "@builder.io/qwik";
import { routeLoader$, routeAction$, Form } from "@builder.io/qwik-city";
import db, { generateApiKey } from "~/lib/db";

// Load all API keys from the database
export const useGetKeys = routeLoader$(async () => {
  const stmt = db.prepare(`
    SELECT id, name, key_prefix as prefix, status, created_at
    FROM api_keys
    ORDER BY id DESC
  `);
  const rows = stmt.all() as any[];
  return rows.map((row) => ({
    id: Number(row.id),
    name: row.name,
    prefix: row.prefix,
    status: row.status,
    created_at: row.created_at,
  }));
});

// Action to generate a new API key
export const useGenerateKey = routeAction$(async (data) => {
  const name = data.name;
  if (!name || typeof name !== "string" || name.trim() === "") {
    return { success: false, error: "Name is required" };
  }

  const { fullKey, prefix, hashedKey } = generateApiKey();
  const createdAt = new Date().toISOString();
  const status = "active";

  const stmt = db.prepare(`
    INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
    VALUES (?, ?, ?, ?, ?)
  `);
  const info = stmt.run(name.trim(), prefix, hashedKey, status, createdAt);
  const insertId = info.lastInsertRowid;

  return {
    success: true,
    key: {
      id: Number(insertId),
      name: name.trim(),
      prefix,
      key: fullKey,
      status,
      created_at: createdAt,
    },
  };
});

// Action to revoke an API key
export const useRevokeKey = routeAction$(async (data) => {
  const id = data.id;
  if (!id) {
    return { success: false, error: "ID is required" };
  }

  const checkStmt = db.prepare("SELECT id FROM api_keys WHERE id = ?");
  const keyExists = checkStmt.get(id);

  if (!keyExists) {
    return { success: false, error: "Key not found" };
  }

  const updateStmt = db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?");
  updateStmt.run(id);

  return { success: true };
});

export default component$(() => {
  const keysSignal = useGetKeys();
  const generateAction = useGenerateKey();
  const revokeAction = useRevokeKey();

  const isCopied = useSignal(false);

  const handleCopy = $(async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      isCopied.value = true;
      setTimeout(() => {
        isCopied.value = false;
      }, 2000);
    } catch (err) {
      console.error("Failed to copy key: ", err);
    }
  });

  const generatedKey = generateAction.value?.key;

  return (
    <div class="container">
      <header>
        <h1>API Key Manager</h1>
        <p class="subtitle">Generate, view, and revoke API keys for your applications.</p>
      </header>

      {/* Prominent success/alert box for newly generated key */}
      {generateAction.value?.success && generatedKey && (
        <div class="alert alert-success">
          <h3>🎉 API Key Generated Successfully!</h3>
          <p>
            Please copy this key and store it somewhere secure. For security reasons,{" "}
            <strong>you will not be able to see it again.</strong>
          </p>
          <div class="key-display">
            <span>{generatedKey.key}</span>
            <button
              type="button"
              class="btn-primary"
              style="padding: 0.25rem 0.75rem; font-size: 0.875rem;"
              onClick$={() => handleCopy(generatedKey.key)}
            >
              {isCopied.value ? "Copied!" : "Copy"}
            </button>
          </div>
        </div>
      )}

      {generateAction.value?.success === false && (
        <div class="alert" style="background-color: var(--danger-bg); border-color: var(--danger-border); color: var(--danger-text);">
          <strong>Error:</strong> {generateAction.value.error}
        </div>
      )}

      {/* Generate Key Form */}
      <div class="card">
        <h2 class="card-title">Generate a New API Key</h2>
        <Form action={generateAction}>
          <div class="form-group">
            <label for="key-name">Key Name / Description</label>
            <div class="input-row">
              <input
                type="text"
                id="key-name"
                name="name"
                placeholder="e.g. Production Frontend, Development Key"
                required
                value={generateAction.value?.success ? "" : undefined}
              />
              <button type="submit" class="btn-primary">
                {generateAction.isRunning ? "Generating..." : "Generate Key"}
              </button>
            </div>
          </div>
        </Form>
      </div>

      {/* Keys Table */}
      <div class="card" style="padding: 0; overflow-x: auto;">
        <h2 class="card-title" style="padding: 1.5rem 1.5rem 0 1.5rem; margin-bottom: 0.5rem;">
          Your API Keys
        </h2>
        {keysSignal.value.length === 0 ? (
          <p style="padding: 0 1.5rem 1.5rem 1.5rem; color: var(--text-muted);">
            No API keys generated yet. Create one above to get started.
          </p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Prefix</th>
                <th>Status</th>
                <th>Created At</th>
                <th style="text-align: right;">Actions</th>
              </tr>
            </thead>
            <tbody>
              {keysSignal.value.map((key) => (
                <tr key={key.id}>
                  <td style="font-weight: 500;">{key.name}</td>
                  <td>
                    <span class="monospace">{key.prefix}</span>
                  </td>
                  <td>
                    <span class={`badge badge-${key.status}`}>{key.status}</span>
                  </td>
                  <td class="text-muted">
                    {new Date(key.created_at).toLocaleString("en-US", {
                      year: "numeric",
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                      second: "2-digit",
                    })}
                  </td>
                  <td style="text-align: right;">
                    <Form action={revokeAction}>
                      <input type="hidden" name="id" value={key.id} />
                      <button
                        type="submit"
                        class="btn-danger"
                        disabled={key.status === "revoked" || revokeAction.isRunning}
                      >
                        {revokeAction.isRunning && revokeAction.formData?.get("id") === String(key.id)
                          ? "Revoking..."
                          : "Revoke"}
                      </button>
                    </Form>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
});
